:root{--im-mission:url(data:image/jpeg;base64,);--im-uchideshi:url(data:image/jpeg;base64,);--im-classes:url(data:image/jpeg;base64,);--im-join:url(data:image/jpeg;base64,);--im-ar:url(data:image/jpeg;base64,)}
.hr[data-img="mission"]{--hphoto:var(--im-mission);--hpos:40% 65%}
.hr[data-img="uchideshi"]{--hphoto:var(--im-uchideshi);--hpos:50% 40%}
.hr[data-img="classes"]{--hphoto:var(--im-classes);--hpos:52% 35%}
.hr[data-img="join"]{--hphoto:var(--im-join);--hpos:50% 0%}
.hr[data-img="ar"]{--hphoto:var(--im-ar);--hpos:center}
.hr[data-img="mission"],.hr[data-img="uchideshi"],.hr[data-img="classes"],.hr[data-img="join"],.hr[data-img="ar"]{background-color:#14171C;background-image:linear-gradient(to bottom,rgba(10,12,16,.6) 0,rgba(10,12,16,0) 130px),linear-gradient(to top,rgba(10,12,16,.88) 0,rgba(10,12,16,.4) 50%,rgba(10,12,16,.1) 100%),var(--hphoto);background-size:cover;background-position:var(--hpos,center);background-repeat:no-repeat}
.hr[data-img="mission"] .pl,.hr[data-img="uchideshi"] .pl,.hr[data-img="classes"] .pl,.hr[data-img="join"] .pl,.hr[data-img="ar"] .pl{display:none}
